(()=>{const buttons=[...document.querySelectorAll('[data-tour-stop]')];if(!buttons.length)return;const stops=[...document.querySelectorAll('.tour-stop')],count=document.getElementById('tour-count');let selected=0;const show=index=>{selected=(index+stops.length)%stops.length;stops.forEach((stop,i)=>stop.hidden=i!==selected);buttons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===selected)));count.textContent=(selected+1)+' / '+stops.length};buttons.forEach((button,i)=>button.addEventListener('click',()=>show(i)));document.getElementById('tour-previous').addEventListener('click',()=>show(selected-1));document.getElementById('tour-next').addEventListener('click',()=>show(selected+1));document.querySelector('.tour-choices').addEventListener('keydown',event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();show(selected+(event.key==='ArrowRight'?1:-1));buttons[selected].focus()}})})();
